//! History compact **decision** authority (Grok-style early compact). //! //! Assembly / LLM summary stays in Python ContextPipeline. This module only //! answers: should we compress, allow L5, hard-truncate, which threshold.  use serde_json::{json, Value};  /// Decide compact policy for the current message list. /// /// Params (JSON): /// - tokens: estimated tokens /// - message_count / n_msg /// - effective_count / n_effective (exclude mid-list system nudges) /// - context_window /// - threshold_percent (default 0.85) /// - soft_n (default 48) /// - hard_n (default 90) /// - micro_only (bool) /// - allow_l5 (bool, default true) /// - history_cap (optional harness hard cap) /// - light_loop / ops_loop (bool) 鈥?thinner caps pub fn decide_compact_from_value(params: &Value) -> Value {     let tokens = params         .get("tokens")         .and_then(|v| v.as_u64())         .or_else(|| params.get("tokens_before").and_then(|v| v.as_u64()))         .unwrap_or(0) as u64;     let n_msg = params         .get("message_count")         .or_else(|| params.get("n_msg"))         .and_then(|v| v.as_u64())         .unwrap_or(0) as usize;     let n_eff = params         .get("effective_count")         .or_else(|| params.get("n_effective"))         .and_then(|v| v.as_u64())         .unwrap_or(n_msg as u64) as usize;     let window = params         .get("context_window")         .and_then(|v| v.as_u64())         .unwrap_or(128_000)         .max(1024);     let mut thr = params         .get("threshold_percent")         .and_then(|v| v.as_f64())         .unwrap_or(0.85)         .clamp(0.3, 0.99);     let soft_n = params         .get("soft_n")         .and_then(|v| v.as_u64())         .unwrap_or(48) as usize;     let hard_n = params         .get("hard_n")         .and_then(|v| v.as_u64())         .unwrap_or(90) as usize;     let micro_only = params         .get("micro_only")         .and_then(|v| v.as_bool())         .unwrap_or(false);     let mut allow_l5 = params         .get("allow_l5")         .and_then(|v| v.as_bool())         .unwrap_or(true);     let light = params         .get("light_loop")         .and_then(|v| v.as_bool())         .unwrap_or(false);     let ops = params         .get("ops_loop")         .and_then(|v| v.as_bool())         .unwrap_or(false);     let history_cap = params         .get("history_cap")         .and_then(|v| v.as_u64())         .unwrap_or(0) as usize;      // Thin harness: tighter soft/hard so chat does not bloat     let soft = if light {         soft_n.min(48).min(history_cap.max(16).min(48))     } else if ops {         soft_n.min(64)     } else {         soft_n     };     let hard = if light {         hard_n.min(64).min(if history_cap > 0 {             history_cap.max(24)         } else {             64         })     } else if ops {         hard_n.min(80)     } else {         hard_n     };      let budget = (window as f64 * thr) as u64;     let token_over = tokens >= budget && budget > 0;     let count_pressure = n_eff >= soft;     let hard_pressure = n_msg >= hard || n_eff >= hard;      // Deepen threshold under count pressure (Python COMPRESS_THRESHOLD_DEEP 鈮?0.75)     if count_pressure && !micro_only {         thr = thr.min(0.75);         allow_l5 = true;     }     if hard_pressure {         allow_l5 = true;     }     if micro_only {         allow_l5 = false;     }      let budget2 = (window as f64 * thr) as u64;     let token_over2 = tokens >= budget2 && budget2 > 0;      let mut reasons: Vec<&str> = Vec::new();     if token_over || token_over2 {         reasons.push("token_threshold");     }     if count_pressure {         reasons.push("count_soft");     }     if hard_pressure {         reasons.push("count_hard");     }      let should_compress = token_over2 || count_pressure || hard_pressure;     // Short lists: skip full pipeline unless forced     let skip_pipeline = !should_compress && n_msg < 8;     let force_hard_truncate = hard_pressure;     let run_l1_only = !should_compress && n_msg >= 8 && n_msg < soft;      json!({         "should_compress": should_compress,         "skip_pipeline": skip_pipeline,         "run_l1_only": run_l1_only,         "force_hard_truncate": force_hard_truncate,         "allow_l5": allow_l5 && !micro_only,         "micro_only": micro_only,         "threshold_percent": thr,         "budget_tokens": budget2,         "tokens": tokens,         "message_count": n_msg,         "effective_count": n_eff,         "soft_n": soft,         "hard_n": hard,         "history_cap": history_cap,         "reasons": reasons,         "authority": "rust",     }) }  #[cfg(test)] mod tests {     use super::*;      #[test]     fn short_chat_no_compress() {         let v = decide_compact_from_value(&json!({             "tokens": 1000,             "message_count": 5,             "effective_count": 5,             "context_window": 128000,             "light_loop": true,         }));         assert_eq!(v["should_compress"], false);         assert_eq!(v["skip_pipeline"], true);     }      #[test]     fn soft_count_triggers() {         let v = decide_compact_from_value(&json!({             "tokens": 1000,             "message_count": 50,             "effective_count": 50,             "context_window": 128000,             "soft_n": 48,             "light_loop": true,         }));         assert_eq!(v["should_compress"], true);         assert_eq!(v["allow_l5"], true);     }      #[test]     fn token_threshold() {         let v = decide_compact_from_value(&json!({             "tokens": 120_000,             "message_count": 10,             "context_window": 128_000,             "threshold_percent": 0.85,         }));         assert_eq!(v["should_compress"], true);         assert!(v["reasons"].as_array().unwrap().iter().any(|r| r == "token_threshold"));     } }